svg.script:
var frame = document.createElementNS('http://www.w3.org/1999/xhtml', 'iframe');
frame.setAttribute('title', 'Pizza Unblocked');
frame.setAttribute('style', 'width:100%;height:100%;border:0;display:block;background:#1e1a16');
frame.setAttribute('allow', 'autoplay; fullscreen; gamepad; cross-origin-isolated');
frame.setAttribute('allowfullscreen', '');
document.getElementById('site').appendChild(frame);
frame.srcdoc = "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"><base href="https://pizza-tower-9iw.pages.dev/">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pizza Unblocked</title>
<link rel="icon" href="assets/favicon-pizza-face.png" type="image/png">
<link rel="apple-touch-icon" href="assets/favicon-pizza-face.png">
<style>/* Pizza Unblocked — toby-web style layout */
@font-face {
    font-family: 'ptsmall';
    src: url('https://cdn.jsdelivr.net/gh/KrisCrossXX/PizzaUnblocked@main/assets/fonts/pizza-tower-small.ttf') format('truetype');
}

:root {
    --bg: #1e1a16;
    --text: #fff4e0;
    --yellow: #ffd75e;
    --muted: #b8a89a;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body { min-height: 100%; min-height: 100dvh; }

body {
    background: var(--bg);
    color: var(--text);
    font-family: 'ptsmall', 'Courier New', monospace;
    min-height: 100vh;
    min-height: 100dvh;
    overflow: hidden;
}

/* ---------- background gif ---------- */
.bgimg {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: fill;
    image-rendering: pixelated;
    z-index: 0;
    pointer-events: none;
}
body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    background: var(--bg);
    pointer-events: none;
}
/* theme variants (applied to .bgimg) */
.bgimg.theme-black      { display: none; }

/* ---------- theme picker ---------- */
.theme-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
    gap: 12px;
}
.theme-card {
    background: #000;
    border: 2px solid #555;
    cursor: pointer;
    padding: 4px 4px 2px;
    text-align: center;
}
.theme-card.sel { border-color: var(--yellow); }
.theme-card .tprev {
    width: 100%;
    aspect-ratio: 16 / 10;
    object-fit: cover;
    object-position: center;
    image-rendering: pixelated;
    display: block;
    background: #000;
    border: 1px solid #333;
}
.theme-card .tprev.theme-black { display: block; }
.theme-card .tname {
    color: #fff;
    font-size: .8rem;
    padding: 5px 0;
    text-transform: uppercase;
    letter-spacing: .04em;
}
.theme-card.sel .tname { color: var(--yellow); }

/* ---------- full theme browser ---------- */
body[data-view="themes"] .logo,
body[data-view="themes"] .topicons,
body[data-view="themes"] .pizza-icon { display: none; }
.themes-page { padding: 0 0 70px; background: rgba(7, 7, 12, .94); }
.themes-topbar {
    position: sticky;
    top: 0;
    z-index: 4;
    display: flex;
    align-items: center;
    gap: 18px;
    min-height: 54px;
    padding: 7px 18px;
    background: #050509;
    border-bottom: 1px solid #aaa;
}
.themes-topbar h1 { font-size: 1.7rem; text-transform: uppercase; }
.theme-back, .theme-nav-btn, .theme-action {
    padding: 5px 10px;
    border: 1px solid #fff;
    background: #000;
    color: #fff;
    font: inherit;
    text-transform: uppercase;
    cursor: pointer;
}
.theme-nav { display: flex; gap: 7px; margin-left: auto; }
.theme-nav-btn.selected, .theme-nav-btn:hover, .theme-back:hover, .theme-action:hover {
    color: var(--yellow);
    border-color: var(--yellow);
}
.theme-view { padding: 20px 18px 30px; }
.theme-view h2 { margin-bottom: 20px; font-size: 1.35rem; }
.theme-view h3 { margin: 16px 0 10px; font-size: 1rem; }
.themes-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; }
.theme-tile { display: flex; flex-direction: column; min-width: 0; background: #000; border: 1px solid #ddd; }
.theme-tile { position: relative; }
.theme-favorite { position: absolute; top: 6px; right: 6px; width: 34px; height: 34px; border: 1px solid #fff; border-radius: 50%; background: #000d; color: var(--yellow); font: inherit; font-size: 1.2rem; cursor: pointer; }
.theme-favorite[aria-pressed="true"] { background: #2a210c; }
.theme-tile.active { border-color: var(--yellow); }
.theme-tile-image {
    display: block;
    width: 100%;
    aspect-ratio: 16 / 10;
    object-fit: cover;
    background: #111;
    border: 0;
    border-bottom: 1px solid #777;
    cursor: pointer;
}
.theme-tile-title { padding: 6px 7px 2px; font-size: .85rem; overflow-wrap: anywhere; }
.theme-tile-creator { padding: 2px 7px 7px; color: var(--muted); font-size: .72rem; }
.theme-tile-actions { display: flex; gap: 5px; margin-top: auto; padding: 0 6px 6px; }
.theme-tile-actions .theme-action { flex: 1; font-size: .72rem; }
.theme-empty { margin: 15px 0; color: var(--muted); }
.theme-catalog-status, .cr-beta-status { margin: 0 0 12px; color: var(--muted); font-size: .8rem; }
.theme-load-more { height: 1px; }
.theme-discover-tools { display: flex; gap: 8px; margin-bottom: 14px; }
.theme-input {
    width: 100%;
    padding: 9px 10px;
    border: 1px solid #ddd;
    border-radius: 0;
    background: #050509;
    color: #fff;
    font: inherit;
}
.theme-discover-tools .theme-input { max-width: 280px; }
.theme-create-layout { display: grid; grid-template-columns: minmax(280px, 1fr) minmax(300px, 1fr); gap: 22px; }
.theme-create-form { display: grid; align-content: start; gap: 12px; }
.theme-form-actions, .theme-draft-tools { display: flex; flex-wrap: wrap; gap: 7px; align-items: center; }
.theme-draft-tools .sel { min-width: 180px; flex: 1; }
.card { font: inherit; color: inherit; text-align: left; cursor: pointer; }
.pop.ost-popup { width: min(760px, 94vw); max-height: 90vh; }
.ost-popup .pop-body { overflow-y: auto; }
.ost-embed { display: block; width: 100%; height: min(60vh, 560px); min-height: 352px; margin: 12px 0 8px; border: 0; background: #000; }
.ost-popup-links { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 10px; }
.ost-popup-links a { color: var(--yellow); font-size: .8rem; }
.theme-create-form > label { display: grid; gap: 5px; color: var(--muted); font-size: .84rem; text-transform: uppercase; }
.theme-file { font-size: .78rem; }
.theme-colors { display: flex; gap: 14px; flex-wrap: wrap; }
.theme-colors label { display: grid; gap: 5px; color: var(--muted); font-size: .8rem; text-transform: uppercase; }
.theme-colors input { width: 56px; height: 36px; border: 1px solid #aaa; background: #000; }
.theme-action.primary { justify-self: start; padding: 8px 18px; }
.theme-form-note, .theme-stats-note { color: var(--muted); font-size: .8rem; }
.theme-preview-wrap h3 { margin-top: 0; }
.theme-preview {
    display: flex;
    min-height: 250px;
    flex-direction: column;
    justify-content: space-between;
    padding: 18px;
    border: 1px solid #ddd;
    background: center / cover #1e1a16;
    color: #fff4e0;
}
.preview-title { align-self: center; padding: 5px 12px; background: #000b; font-size: 1.25rem; text-transform: uppercase; }
.preview-buttons { display: flex; justify-content: space-around; gap: 6px; }
.theme-preview[data-layout="center"] .preview-buttons { align-items: center; flex-direction: column; }
.theme-preview[data-layout="left"] .preview-buttons { align-items: flex-start; flex-direction: column; }
.theme-preview[data-layout="right"] .preview-buttons { align-items: flex-end; flex-direction: column; }
.preview-buttons i { padding: 7px; background: #000c; border: 1px solid #ffd75e; font-style: normal; text-transform: uppercase; }
.theme-stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 10px; }
.theme-stat { display: flex; justify-content: space-between; gap: 10px; padding: 12px; border: 1px solid #aaa; background: #000; }
.theme-stat strong { color: var(--yellow); text-align: right; }



/* ---------- chrome ---------- */
.logo {
    position: fixed;
    top: 10px; left: 14px;
    z-index: 5;
    display: flex;
    align-items: center;
    gap: 14px;
    text-decoration: none;
}
.logo img {
    display: block;
    height: clamp(110px, 21vh, 190px);
    width: auto;
}
.byline {
    color: #ff3b3b;
    font-size: 1.3rem;
    letter-spacing: .03em;
    white-space: nowrap;
    padding-top: 22px;
}

.topicons {
    position: fixed;
    top: 12px; right: 14px;
    display: flex;
    gap: 8px;
    z-index: 10;
}
.icon-btn {
    display: grid;
    place-items: center;
    width: 74px; height: 66px;
    padding: 4px;
    background: transparent;
    border: none;
    cursor: pointer;
}
.icon-btn img {
    width: 100%; height: 100%;
    object-fit: contain;
    display: block;
}
.icon-btn:hover img { filter: brightness(1.25); }
.icon-btn:active { transform: translateY(2px); }

/* ---------- menu ---------- */
.menu {
    position: relative;
    z-index: 1;
    height: 100vh;
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-content: start;
    align-items: center;
    gap: 1vh 4vw;
    padding: 18vh 8vw 100px;
    overflow-y: auto;
}
.menu .gbtn:first-child { justify-self: start; }
.menu .gbtn:nth-child(2) { justify-self: end; }
.menu .gbtn:nth-child(3) { grid-column: 1 / -1; justify-self: center; }
.menu[data-theme-layout="center"] { grid-template-columns: 1fr; justify-items: center; }
.menu[data-theme-layout="center"] .gbtn,
.menu[data-theme-layout="center"] .home-game-entry,
.menu[data-theme-layout="center"] .gbtn:nth-child(3) { grid-column: 1; justify-self: center !important; }
.menu[data-theme-layout="left"] { grid-template-columns: 1fr; justify-items: start; }
.menu[data-theme-layout="left"] .gbtn,
.menu[data-theme-layout="left"] .home-game-entry,
.menu[data-theme-layout="left"] .gbtn:nth-child(3) { grid-column: 1; justify-self: start !important; }
.menu[data-theme-layout="right"] { grid-template-columns: 1fr; justify-items: end; }
.menu[data-theme-layout="right"] .gbtn,
.menu[data-theme-layout="right"] .home-game-entry,
.menu[data-theme-layout="right"] .gbtn:nth-child(3) { grid-column: 1; justify-self: end !important; }
.home-game-entry { position: relative; display: inline-block; width: fit-content; justify-self: start; }
.home-game-entry .favorite-toggle { top: -8px; right: -8px; }

.library-launch {
    grid-column: 1 / -1;
    justify-self: center;
    margin: 12px 0 28px;
    padding: 9px 22px;
    border: 2px solid var(--yellow);
    background: #000;
    color: var(--yellow);
    font-size: 1.15rem;
    letter-spacing: .04em;
    text-decoration: none;
    text-transform: uppercase;
}
.library-launch:hover, .shelf-link:hover { background: var(--yellow); color: #000; }
.site-version {
    display: inline-block;
    color: #80db79;
    border: 1px solid currentColor;
    padding: 3px 8px;
    font-size: .78rem;
    letter-spacing: .06em;
}
.menu > .site-version { grid-column: 1 / -1; justify-self: center; margin: -24px 0 16px; }
.library-heading .site-version { margin-left: 8px; vertical-align: middle; }

.home-shelf {
    grid-column: 1 / -1;
    width: min(1120px, 100%);
    justify-self: center;
    margin: 0 auto 22px;
    padding: 14px 16px 18px;
    background: rgba(0, 0, 0, .82);
    border: 2px solid rgba(255, 215, 94, .7);
}
.shelf-heading {
    display: flex;
    align-items: baseline;
    gap: 12px;
    margin-bottom: 12px;
    flex-wrap: wrap;
}
.shelf-heading h2 { color: var(--yellow); font-size: 1.2rem; text-transform: uppercase; }
.shelf-heading span { color: var(--muted); font-size: .85rem; }
.shelf-link {
    margin-left: auto;
    padding: 4px 10px;
    border: 1px solid var(--yellow);
    background: #000;
    color: var(--yellow);
    font: inherit;
    cursor: pointer;
}
.shelf-grid {
    width: 100%;
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: 12px;
}
.shelf-grid:empty { display: none; }
.home-shelf .empty-note { margin: 8px 0 0; }

.library-page { padding-top: 125px; }
.library-heading { width: min(1200px, 94vw); margin: 0 auto 14px; text-align: center; }
.library-heading h1 { color: var(--yellow); font-size: clamp(1.6rem, 4vw, 2.4rem); text-transform: uppercase; }
.library-heading p { color: var(--muted); margin-top: 4px; }
.library-toolbar {
    display: flex;
    width: min(1200px, 94vw);
    margin: 0 auto 22px;
    gap: 12px;
    align-items: end;
    flex-wrap: wrap;
}
.library-filters { display: flex; gap: 7px; flex-wrap: wrap; flex: 1 1 100%; }
.library-filter {
    padding: 7px 12px;
    border: 2px solid #fff;
    background: #000;
    color: #fff;
    font: inherit;
    text-transform: uppercase;
    cursor: pointer;
}
.library-filter:hover, .library-filter.selected { color: var(--yellow); border-color: var(--yellow); }
.catalog-toolbar {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    width: min(1100px, 94vw);
    margin: 0 auto 26px;
}
.catalog-search {
    flex: 0 0 auto;
    width: min(480px, 80vw);
    margin: 0;
    padding: 10px 16px;
    font-size: 1.15rem;
}
.catalog-filters { display: flex; width: min(480px, 80vw); gap: 5px; flex-wrap: wrap; }
.catalog-filter {
    min-height: 34px;
    padding: 5px 12px;
    border: 1px solid #fff;
    background: #fff;
    color: #111;
    font: inherit;
    font-size: .9rem;
    text-transform: uppercase;
    cursor: pointer;
}
.catalog-filter:hover, .catalog-filter.selected { background: #111; color: var(--yellow); border-color: var(--yellow); }
.catalog-filter:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
.library-select-label { display: grid; gap: 4px; color: var(--muted); font-size: .82rem; text-transform: uppercase; }
.library-select { min-width: 170px; }
.library-grid { width: min(1200px, 94vw); }

.gbtn { display: block; }
.gbtn img {
    display: block;
    width: clamp(261px, 29.6vw, 487px);
    height: auto;
    transition: transform .1s;
}
.gbtn:hover img { transform: scale(1.05); }
.gbtn:active img { transform: scale(.97); }

/* ---------- pizza icon bottom-left ---------- */
.pizza-icon {
    position: fixed;
    bottom: 14px; left: 14px;
    width: 100px;
    z-index: 5;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0;
}
.presence-count {
    position: absolute;
    left: calc(100% + 8px);
    bottom: 5px;
    white-space: nowrap;
    padding: 4px 8px;
    border: 1px solid rgba(255,255,255,.65);
    border-radius: 999px;
    background: rgba(25, 18, 18, .9);
    color: #39e75f;
    font: 12px/1.2 'ptsmall', 'Courier New', monospace;
    text-shadow: 0 1px 2px #000, 0 0 5px rgba(57, 231, 95, .65);
    pointer-events: none;
}
.pizza-icon img { width: 100%; display: block; }
.pizza-icon:hover img { filter: brightness(1.2); }

/* ---------- popups ---------- */
.overlay {
    position: fixed;
    inset: 0;
    z-index: 50;
    background: rgba(0, 0, 0, .6);
    display: grid;
    place-items: center;
}
.overlay[hidden] { display: none; }
.menu[hidden], .page[hidden] { display: none; }

.pop {
    position: relative;
    width: min(860px, 94vw);
    max-height: 92vh;
    overflow-y: auto;
    background: #000;
    border: 2px solid #fff;
    padding: 16px 22px 22px;
}
.pop-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
}
.pop-title {
    font-size: 1.6rem;
    color: var(--yellow);
    letter-spacing: .05em;
}
.xbtn {
    width: 34px; height: 34px;
    background: #000;
    color: #fff;
    border: 2px solid #fff;
    font-family: inherit;
    font-size: 1.2rem;
    line-height: 1;
    cursor: pointer;
}
.xbtn:hover { background: var(--yellow); color: #000; border-color: var(--yellow); }

/* settings popup */
.set-block { margin-bottom: 18px; }
.set-label {
    color: var(--yellow);
    font-size: 1.05rem;
    margin-bottom: 8px;
}
.opt-row {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    align-items: center;
    margin-bottom: 8px;
}
.sbtn {
    font-family: inherit;
    font-size: .95rem;
    color: #fff;
    background: #000;
    border: 2px solid #fff;
    padding: 8px 14px;
    cursor: pointer;
    min-width: 150px;
    text-align: left;
}
.sbtn:hover { border-color: var(--yellow); color: var(--yellow); }
.sbtn.sel { color: var(--yellow); border-color: var(--yellow); }
.crashlog {
    max-height: 160px;
    overflow-y: auto;
    margin: 0 0 8px;
    padding: 8px;
    background: rgba(0,0,0,.6);
    border: 1px solid #555;
    font-family: 'Courier New', monospace;
    font-size: .8rem;
    color: #ccc;
    white-space: pre-wrap;
    word-break: break-all;
}
.sel {
    font-family: inherit;
    font-size: .95rem;
    color: #fff;
    background: #000;
    border: 2px solid #fff;
    padding: 8px;
    min-width: 200px;
}
.sel:focus { outline: none; border-color: var(--yellow); }
.vol {
    -webkit-appearance: none;
    appearance: none;
    width: 180px;
    height: 10px;
    background: #333;
    border: 1px solid #fff;
}
.vol::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 16px; height: 16px;
    background: var(--yellow);
    border: 1px solid #fff;
    cursor: pointer;
}
.vol::-moz-range-thumb {
    width: 16px; height: 16px;
    background: var(--yellow);
    border: 1px solid #fff;
    cursor: pointer;
}

/* device line */
.devline { color: var(--muted); font-size: .85rem; margin-top: 6px; }

/* changelog popup */
.cl-head { margin: 14px 0 6px; }
.cl-title { color: var(--yellow); font-size: 1.2rem; }
.cl-date { color: var(--yellow); font-size: .95rem; opacity: .85; }
.cl-label { color: var(--yellow); font-size: 1rem; margin: 8px 0 4px; }
.cl-list { list-style: none; }
.cl-list li {
    color: #fff;
    font-size: .95rem;
    padding: 2px 0 2px 14px;
}
.cl-list li::before { content: '- '; color: var(--yellow); }

/* ---------- card pages (mods / extras) ---------- */
.page {
    position: relative;
    z-index: 1;
    min-height: 100vh;
    padding: 130px 6vw 90px;
    overflow-y: auto;
    max-height: 100vh;
}
.searchbox {
    display: block;
    width: min(480px, 80vw);
    margin: 0 auto 26px;
    padding: 10px 16px;
    font-family: inherit;
    font-size: 1.15rem;
    color: var(--yellow);
    background: rgba(0,0,0,.75);
    border: 2px solid #fff;
    border-radius: 0;
    outline: none;
}
.searchbox::placeholder { color: var(--muted); }
.searchbox:focus { border-color: var(--yellow); }
.card-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
    gap: 22px;
    width: min(1000px, 94vw);
    margin: 0 auto;
}
.card {
    display: block;
    text-decoration: none;
    background: #000;
    border: 2px solid #fff;
}
.card:hover { border-color: var(--yellow); }
.card .thumb {
    position: relative;
    aspect-ratio: 4 / 3;
    display: grid;
    place-items: center;
    background: #000;
    overflow: hidden;
}
.library-card { position: relative; min-width: 0; }
.library-card .card { height: 100%; }
.library-card .thumb img { width: 88%; height: 88%; object-fit: contain; }
.favorite-toggle {
    position: absolute;
    top: 7px;
    right: 7px;
    z-index: 2;
    width: 34px;
    height: 34px;
    border: 1px solid #fff;
    border-radius: 50%;
    background: rgba(0,0,0,.9);
    color: #fff;
    font-size: 1.2rem;
    line-height: 1;
    cursor: pointer;
}
.favorite-toggle:hover, .favorite-toggle[aria-pressed="true"] { color: var(--yellow); border-color: var(--yellow); }
.card-tags { display: flex; justify-content: center; flex-wrap: wrap; gap: 5px; padding: 6px 8px 0; }
.library-tag-pill {
    padding: 2px 6px;
    border: 1px solid #655a45;
    color: var(--muted);
    font-size: .7rem;
    text-transform: uppercase;
}
.card .cdesc { padding: 5px 9px 9px; color: var(--muted); text-align: center; font-size: .8rem; }
.card .thumb img {
    max-width: 88%;
    max-height: 88%;
    image-rendering: pixelated;
}
.card .dots {
    position: absolute;
    top: 6px; right: 6px;
    width: 26px; height: 26px;
    background: rgba(0,0,0,.75);
    border: 1px solid #fff;
    color: #fff;
    font-family: inherit;
    cursor: pointer;
}
.card .cname {
    padding: 8px 10px;
    color: var(--yellow);
    font-size: 1rem;
    text-align: center;
    border-top: 2px solid #fff;
}
.empty-note {
    text-align: center;
    color: var(--muted);
    margin-top: 40px;
    font-size: 1rem;
}

@media (max-width: 720px) {
    .themes-topbar { flex-wrap: wrap; gap: 8px; padding: 7px 10px; }
    .themes-topbar h1 { font-size: 1.3rem; }
    .theme-nav { order: 3; width: 100%; margin-left: 0; }
    .theme-nav-btn { flex: 1; padding: 5px 4px; font-size: .82rem; }
    .theme-view { padding: 16px 10px 24px; }
    .themes-grid { grid-template-columns: repeat(auto-fill, minmax(135px, 1fr)); gap: 8px; }
    .theme-create-layout { grid-template-columns: 1fr; }
    .menu { grid-template-columns: 1fr; gap: 20px; padding: 132px 5vw 100px; }
    .home-game-entry { justify-self: center; }
    .menu .gbtn { justify-self: center !important; }
    .menu .gbtn:nth-child(3) { grid-column: auto; }
    .library-launch, .home-shelf { grid-column: auto; }
    .logo img { height: 110px; max-width: 62vw; object-fit: contain; }
    .byline { font-size: 1rem; padding-top: 14px; }
    .icon-btn { width: 58px; height: 52px; }
    .gbtn img { width: min(487px, 74vw); }
    .pizza-icon { width: 64px; }
    .sbtn { min-width: 0; flex: 1; }
    .sel { min-width: 0; width: 100%; }
    /* prevent iOS focus-zoom */
    .sel, .searchbox, input { font-size: 16px; }
    .catalog-search { width: min(480px, 90vw); }
    .catalog-filters { width: min(480px, 90vw); }
    .catalog-filter { min-height: 38px; }
    .pop { padding: 12px 14px 16px; }
    .card-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 14px; }
    .shelf-grid { grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); }
    .library-toolbar { align-items: stretch; }
    .library-select-label { flex: 1; }
    .library-select { width: 100%; min-width: 0; }
    .vol { flex: 1; }
}

@media (max-width: 420px) {
    .logo img { height: 84px; }
    .icon-btn { width: 48px; height: 44px; }
    .topicons { gap: 4px; }
    .menu { padding: 96px 0 90px; }
    .pop-title { font-size: 1.25rem; }
    .card-grid { grid-template-columns: 1fr 1fr; }
}

/* save popup */
.pop-save { width: min(430px, 92vw); }
.pop-save .save-desc { font-size: .95rem; line-height: 1.55; margin: 0 0 14px; }
.pop-save .savebtns { display: grid; gap: 9px; }
.pop-save .savebtns .sbtn { width: 100%; }

/* game overlay — in-page iframe so game URLs never hit the address bar */
#gameOverlay { position: fixed; inset: 0; z-index: 500; width: 100vw; height: 100vh; height: 100dvh; background: #000; display: flex; flex-direction: column; }
#gameOverlay iframe { flex: 1; width: 100%; border: 0; display: block; background: #000; }
#gameOverlay .game-home { position: absolute; top: max(12px, env(safe-area-inset-top)); left: max(12px, env(safe-area-inset-left)); z-index: 1; padding: 8px 14px; border: 2px solid #ffd75e; border-radius: 6px; background: #14100ce6; color: #ffd75e; font-family: 'ptsmall', 'Courier New', monospace; font-size: 24px; line-height: 1; text-shadow: 2px 2px #000; cursor: pointer; }
#gameOverlay .game-home:hover { background: #352510; }
#gameOverlay .game-home:focus-visible { outline: 3px solid white; outline-offset: 3px; }
.cr-game[href] { color: inherit; text-decoration: none; cursor: pointer; }
.cr-game[href]:hover { border-color: #ffd75e; background: #352510; }
.cr-game[href]:focus-visible { outline: 3px solid #ffd75e; outline-offset: 3px; }
.cr-link-label { display: block; margin-top: 4px; color: #ffd75e; font-size: 12px; }

/* credits page — toby-style cards */
.cr-wrap { width: min(1100px, 94vw); margin: 12vh auto 40px; }
.cr-head { font-family: 'PT Pig', monospace; font-size: 2rem; color: #ffd75e; margin: 26px 0 12px; text-shadow: 0 2px 0 #000; }
.cr-row { display: flex; flex-wrap: wrap; gap: 12px; }
.cr-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 10px; }
.cr-card { display: flex; align-items: center; gap: 10px; background: rgba(20,16,12,.92); border: 2px solid #4a3a2a; border-radius: 10px; padding: 10px 12px; min-width: 0; }
.cr-ava { width: 72px; height: 72px; object-fit: cover; border-radius: 10px; background: #241d16; flex: 0 0 72px; }
.cr-letter { display: flex; align-items: center; justify-content: center; font-family: 'PT Pig', monospace; font-size: 2.2rem; color: #ffd75e; }
.cr-info { display: flex; flex-direction: column; min-width: 0; }
.cr-name { color: #fff4e0; font-size: 1rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cr-role { color: #b8a89a; font-size: .85rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cr-row-tiny { margin-top: 10px; }
.cr-tiny { padding: 6px 10px; border-radius: 8px; }
.cr-tiny .cr-ava { width: 46px; height: 46px; flex-basis: 46px; }
.cr-tiny .cr-letter { font-size: 1.4rem; }
.cr-tiny .cr-name { font-size: .85rem; }
.cr-tiny .cr-role { font-size: .72rem; }
</style>
<script>
// deep links like index.html/extras break relative asset paths —
// bounce to the hash form before any resources load; the router
// rewrites the URL back to the clean path afterwards.
(function () {
    var m = location.pathname.match(/^(.*?)\/index\.html\/(mods|extras|library|credits|themes)\/?$/) || location.pathname.match(/^(.*?)\/(mods|extras|library|credits|themes)\/?$/);
    if (m) location.replace(m[1] + '/index.html#/' + m[m.length - 1]);
})();
</script>
</head>
<body>

<img class="bgimg" src="assets/bg.gif" alt="" aria-hidden="true">

<a class="logo" href="credits.html"><img src="assets/logo.png" alt="Pizza Unblocked"></a>

<nav class="topicons">
    <button class="icon-btn" id="gearBtn" data-sfx="buttons" title="settings"><img src="assets/icon-gear.png" alt="settings"></button>
    <button class="icon-btn" id="clBtn" data-sfx="buttons" title="changelog"><img src="assets/icon-pillar.png" alt="changelog"></button>
    <button class="icon-btn" id="dlBtn" data-sfx="buttons" title="discord"><img src="assets/icon-arrow.png" alt="discord"></button>
    <button class="icon-btn" id="themeBtn" data-sfx="buttons" title="themes"><img src="assets/icon-themes.png" alt="themes"></button>
</nav>

<main class="menu" id="pageHome">
    <div class="home-game-entry">
        <a class="gbtn" href="games/pizzatower/" data-game-key="game%3Apizzatower" data-sfx="pizzatower"><img src="assets/btn-pizzatower.png" alt="PIZZA TOWER"></a>
        <button class="favorite-toggle" type="button" data-game-key="game%3Apizzatower" aria-label="Add Pizza Tower to favorites" aria-pressed="false" title="add favorite">☆</button>
    </div>
    <a class="gbtn" href="mods.html" data-sfx="mods"><img src="assets/btn-mods.png" alt="MODS"></a>
    <a class="gbtn" href="extras.html" data-sfx="extras"><img src="assets/btn-extras.png" alt="EXTRAS"></a>
</main>

<main class="page themes-page" id="pageThemes" hidden>
    <header class="themes-topbar">
        <button class="theme-back" id="themeBack" type="button">back</button>
        <h1>themes</h1>
        <nav class="theme-nav" id="themeNav" aria-label="Theme pages">
            <button class="theme-nav-btn selected" type="button" data-theme-tab="mine">my themes</button>
            <button class="theme-nav-btn" type="button" data-theme-tab="discover">discover</button>
            <button class="theme-nav-btn" type="button" data-theme-tab="create">create</button>
            <button class="theme-nav-btn" type="button" data-theme-tab="stats">stats</button>
        </nav>
    </header>

    <section class="theme-view" id="themeViewMine">
        <h2>my themes</h2>
        <h3>official themes</h3>
        <div class="themes-grid" id="themeOfficialGrid"></div>
        <h3>installed themes</h3>
        <div class="themes-grid" id="themeInstalledGrid"></div>
        <p class="theme-empty" id="themeInstalledEmpty" hidden>no custom themes installed yet</p>
    </section>

    <section class="theme-view" id="themeViewDiscover" hidden>
        <h2>discover</h2>
        <div class="theme-discover-tools">
            <input class="theme-input" id="themeSearch" type="search" placeholder="search themes..." autocomplete="off">
            <select class="sel" id="themeSort" aria-label="Sort themes">
                <option value="newest">newest</option>
                <option value="az">A–Z</option>
                <option value="favorites">favorites</option>
            </select>
        </div>
        <p class="theme-catalog-status" id="themeCatalogStatus" role="status">community catalog is temporarily unavailable; showing built-in themes</p>
        <div class="themes-grid" id="themeDiscoverGrid"></div>
        <div id="themeDiscoverMore" class="theme-load-more" aria-hidden="true"></div>
        <p class="theme-empty" id="themeDiscoverEmpty" hidden>no themes match your search</p>
    </section>

    <section class="theme-view" id="themeViewCreate" hidden>
        <h2>create theme</h2>
        <div class="theme-create-layout">
            <form class="theme-create-form" id="themeCreateForm">
                <label>theme name<input class="theme-input" id="themeName" maxlength="36" required placeholder="my theme"></label>
                <label>creator<input class="theme-input" id="themeCreator" maxlength="36" placeholder="local creator"></label>
                <label>description<textarea class="theme-input" id="themeDescription" maxlength="180" rows="3" placeholder="a short description"></textarea></label>
                <label>background image (up to 30 MB)<input class="theme-input theme-file" id="themeBackground" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label>
                <label>music (up to 50 MB)<input class="theme-input theme-file" id="themeMusic" type="file" accept="audio/mpeg,audio/ogg,audio/wav,audio/mp4,audio/aac"></label>
                <label>home button layout
                    <select class="sel" id="themeButtonLayout">
                        <option value="default">default</option>
                        <option value="center">stacked center</option>
                        <option value="left">stacked left</option>
                        <option value="right">stacked right</option>
                    </select>
                </label>
                <div class="theme-colors">
                    <label>accent<input id="themeAccent" type="color" value="#ffd75e"></label>
                    <label>text<input id="themeText" type="color" value="#fff4e0"></label>
                    <label>background<input id="themeColorBg" type="color" value="#1e1a16"></label>
                </div>
                <div class="theme-form-actions">
                    <button class="theme-action primary" type="submit">save theme</button>
                    <button class="theme-action" id="themeSaveDraft" type="button">save draft</button>
                </div>
                <div class="theme-draft-tools">
                    <select class="sel" id="themeDraftSelect" aria-label="Saved theme drafts"><option value="">select a draft</option></select>
                    <button class="theme-action" id="themeLoadDraft" type="button">load</button>
                    <button class="theme-action" id="themeDeleteDraft" type="button">delete</button>
                </div>
                <p class="theme-form-note" id="themeFormNote" aria-live="polite">themes are saved in this browser</p>
            </form>
            <div class="theme-preview-wrap">
                <h3>preview</h3>
                <div class="theme-preview" id="themePreview">
                    <span class="preview-title">pizza unblocked</span>
                    <span class="preview-buttons"><i>pizza tower</i><i>mods</i><i>extras</i></span>
                </div>
            </div>
        </div>
    </section>

    <section class="theme-view" id="themeViewStats" hidden>
        <h2>theme stats</h2>
        <p class="theme-stats-note">your theme activity on this device</p>
        <div class="theme-stats-grid" id="themeStats"></div>
    </section>
</main>

<main class="page library-page" id="pageLibrary" hidden>
    <div class="library-heading">
        <h1>game library</h1>
        <p>find a game, pick a tag, and sort the collection <span class="site-version">v1.2</span></p>
    </div>
    <input class="searchbox" id="librarySearch" type="search" placeholder="search games and mods..." autocomplete="off" spellcheck="false">
    <div class="library-toolbar">
        <div class="library-filters" id="libraryFilters" role="group" aria-label="Filter games">
            <button class="library-filter selected" type="button" data-library-filter="all">all</button>
            <button class="library-filter" type="button" data-library-filter="mod">mods</button>
            <button class="library-filter" type="button" data-library-filter="game">games</button>
            <button class="library-filter" type="button" data-library-filter="extra">extras</button>
            <button class="library-filter" type="button" data-library-filter="web">web games</button>
            <button class="library-filter" type="button" data-library-filter="favorites">favorites ★</button>
        </div>
        <label class="library-select-label">tag
            <select class="sel library-select" id="libraryTag">
                <option value="all">all tags</option>
                <option value="save">save supported</option>
                <option value="online">online play</option>
                <option value="web">web game</option>
            </select>
        </label>
        <label class="library-select-label">sort
            <select class="sel library-select" id="librarySort">
                <option value="az">A–Z</option>
                <option value="za">Z–A</option>
                <option value="recent">recently played</option>
                <option value="most">most played</option>
            </select>
        </label>
    </div>
    <div class="card-grid library-grid" id="libraryGrid"></div>
    <p class="empty-note" id="libraryEmpty" hidden>no games match those filters</p>
</main>

<main class="page" id="pageMods" hidden>
    <div class="catalog-toolbar">
        <input class="searchbox catalog-search" id="modSearch" type="search" placeholder="search..." autocomplete="off" spellcheck="false">
        <nav class="catalog-filters" id="modFilters" aria-label="Filter mods">
            <button class="catalog-filter" type="button" data-catalog-filter="favorites" aria-pressed="false">favorites</button>
            <button class="catalog-filter" type="button" data-catalog-filter="lap" aria-pressed="false">lap mods</button>
        </nav>
    </div>
    <div class="card-grid" id="modGrid"></div>
    <p class="empty-note" id="modsEmpty" hidden>no mods yet</p>
</main>

<main class="page" id="pageExtras" hidden>
    <div class="catalog-toolbar">
        <input class="searchbox catalog-search" id="extraSearch" type="search" placeholder="search..." autocomplete="off" spellcheck="false">
        <nav class="catalog-filters" id="extraFilters" aria-label="Filter extras">
            <button class="catalog-filter" type="button" data-catalog-filter="favorites" aria-pressed="false">favorites</button>
            <button class="catalog-filter" type="button" data-catalog-filter="lap" aria-pressed="false">lap mods</button>
        </nav>
    </div>
    <div class="card-grid" id="extraGrid"></div>
    <p class="empty-note" id="extrasEmpty" hidden>no extras yet</p>
</main>

<div class="overlay" id="ptSoundtrackPopup" hidden>
    <section class="pop ost-popup" role="dialog" aria-modal="true" aria-labelledby="ptSoundtrackTitle">
        <div class="pop-head">
            <span class="pop-title" id="ptSoundtrackTitle">PT soundtrack player</span>
            <button class="xbtn" type="button" data-close="ptSoundtrackPopup" aria-label="Close soundtrack player">x</button>
        </div>
        <div class="pop-body">
            <p class="theme-form-note">The original itch.io player plays its hosted OGG soundtrack tracks. Use the arrow keys to change tracks and Space to pause.</p>
            <iframe id="ptSoundtrackEmbed" class="ost-embed" title="Pizza Tower OGG soundtrack player" allow="autoplay; fullscreen" allowfullscreen loading="lazy"></iframe>
            <div class="ost-popup-links">
                <a href="https://jasonberlk.itch.io/pizza-tower-soundtrack-player" target="_blank" rel="noopener noreferrer">open the itch.io soundtrack player</a>
            </div>
        </div>
    </section>
</div>

<main class="page" id="pageCredits" hidden>
    <div class="cr-wrap">
        <h2 class="cr-head">site credits</h2>
        <div class="cr-row" id="crSite"></div>
        <h2 class="cr-head">beta testers</h2>
        <p class="cr-beta-status" id="crBetaStatus" role="status">showing saved beta tester credits</p>
        <div class="cr-row cr-row-tiny" id="crBeta"></div>
        <h2 class="cr-head">game credits</h2>
        <div class="cr-grid" id="crGames"></div>
    </div>
</main>

<button class="pizza-icon" data-sfx="buttons" onclick="showPage('home')" title="home"><img src="assets/pizza-icon.png" alt="pizza"><span class="presence-count" id="viewerCount" aria-live="polite">-- viewing</span></button>

<!-- popups -->
<div class="overlay" id="popSettings" hidden>
    <div class="pop">
        <div class="pop-head">
            <span class="pop-title">settings</span>
            <button class="xbtn" data-close="popSettings">x</button>
        </div>
        <div class="pop-body">
            <div class="set-block">
                <div class="set-label">audio</div>
                <div class="opt-row"><button class="sbtn" id="audioBtn">audio: on</button>
                <input class="vol" id="volSlider" type="range" min="0" max="100" value="100"></div>
            </div>
            <div class="set-block">
                <div class="set-label">site name</div>
                <div class="opt-row">
                    <select id="cloakSel" class="sel">
                        <option value="">pizza unblocked</option>
                        <option value="google">google</option>
                        <option value="canvas">canvas</option>
                        <option value="clever">clever</option>
                        <option value="drive">google drive</option>
                        <option value="classroom">google classroom</option>
                    </select>
                </div>
                <div class="opt-row">
                    <button class="sbtn" id="onlineBtn">online counter: on</button>
                    <button class="sbtn" id="panicBtn">panic button: off</button>
                </div>
                <div class="opt-row">
                    <button class="sbtn" id="blankBtn">open in about:blank</button>
                    <button class="sbtn" id="blobBtn">open as blob</button>
                </div>
            </div>
            <div class="set-block">
                <div class="set-label">background</div>
                <div class="theme-grid" id="themeGrid"></div>
            </div>
            <div class="set-block">
                <div class="set-label">tools</div>
                <div class="opt-row">
                    <button class="sbtn" id="padBtn">controller: on</button>
                </div>
                <label class="set-label" for="touchModeSel">mobile controls</label>
                <div class="opt-row">
                    <select id="touchModeSel" class="sel" aria-label="Mobile controls mode">
                        <option value="auto">auto detect</option>
                        <option value="on">on</option>
                        <option value="off">off</option>
                    </select>
                    <select id="touchLayoutSel" class="sel" aria-label="Mobile movement controls">
                        <option value="joystick">joystick</option>
                        <option value="arrows">arrow buttons</option>
                    </select>
                </div>
                <div class="devline" id="devLine">device: pc</div>
            </div>
            <div class="set-block">
                <div class="set-label">crash log</div>
                <pre class="crashlog" id="crashLog">no crashes logged</pre>
                <div class="opt-row">
                    <button class="sbtn" id="copyLogBtn">copy</button>
                    <button class="sbtn" id="clearLogBtn">clear</button>
                </div>
            </div>
        </div>
    </div>
</div>


<div class="overlay" id="popSave" hidden>
    <div class="pop pop-save">
        <div class="pop-head">
            <span class="pop-title" id="saveTitle">noise update mod</span>
            <button class="xbtn" data-close="popSave">x</button>
        </div>
        <div class="pop-body">
            <p class="save-desc">this mod shares save files with other pizza tower games. load the 101% all-p-ranks save or keep your own.</p>
            <div class="savebtns">
                <button class="sbtn" id="saveBackup">back up my save</button>
                <button class="sbtn" id="saveInject">play with 101% save</button>
                <button class="sbtn" id="saveKeep">play with my save</button>
                <button class="sbtn" id="saveCancel">cancel</button>
            </div>
        </div>
    </div>
</div>

<div class="overlay" id="popSoon" hidden>
    <div class="pop">
        <div class="pop-head">
            <span class="pop-title">download</span>
            <button class="xbtn" data-close="popSoon">x</button>
        </div>
        <div class="pop-body">
            <p>grab the single-file build — share it and it loads the site without the url ever touching history:</p>
            <div class="savebtns">
                <button class="sbtn" id="dlHtml">single-file.html</button>
                <button class="sbtn" id="dlSvg">single-file.svg</button>
            </div>
        </div>
    </div>
</div>

<div class="overlay" id="popChangelog" hidden>
    <div class="pop pop-cl">
        <div class="pop-head">
            <span class="pop-title">changelog</span>
            <button class="xbtn" data-close="popChangelog">x</button>
        </div>
        <div class="pop-body" id="clBody"></div>
    </div>
</div>

