function creditImage(path) {
    if (!path.startsWith('assets/')) return path;
    if (window.PU_HOST) return new URL(path, window.PU_HOST.replace(/\/?$/, '/') ).href;
    if (location.protocol === 'file:') return new URL(path, location.pathname.replace(/[^/]*$/, '')).href;
    return new URL(path, location.origin + '/').href;
}

function renderCredits() {
    const site = document.getElementById('crSite');
    const games = document.getElementById('crGames');
    if (!site || !games) return;
    site.innerHTML = '';
    for (const c of SITE_CREDITS) {
        const card = document.createElement('div');
        card.className = 'cr-card';
        card.innerHTML =
            (c.img ? `<img class="cr-ava" src="${creditImage(c.img)}" alt="">` : `<span class="cr-ava cr-letter">${c.name[0]}</span>`) +
            `<span class="cr-info"><span class="cr-name">${c.name}</span><span class="cr-role">${c.role}</span></span>`;
        site.appendChild(card);
    }
    const helpers = document.getElementById('crBeta');
    function renderBetaHelpers(list) {
        helpers.replaceChildren();
        for (const c of list) {
            const card = document.createElement('div');
            card.className = 'cr-card cr-tiny';
            const avatar = document.createElement(c.img ? 'img' : 'span');
            avatar.className = c.img ? 'cr-ava' : 'cr-ava cr-letter';
            if (c.img) { avatar.src = creditImage(c.img); avatar.alt = ''; }
            else avatar.textContent = (c.name || '?').slice(0, 1);
            const info = document.createElement('span'); info.className = 'cr-info';
            const name = document.createElement('span'); name.className = 'cr-name'; name.textContent = c.name || 'beta tester';
            const role = document.createElement('span'); role.className = 'cr-role'; role.textContent = c.role || 'beta testing';
            info.append(name, role); card.append(avatar, info); helpers.appendChild(card);
        }
    }
    renderBetaHelpers(SITE_HELPERS);
    const betaStatus = document.getElementById('crBetaStatus');
    async function refreshBetaTesters() {
        if (location.protocol === 'file:') {
            betaStatus.textContent = 'showing saved credits; live Discord list works on the hosted site';
            return;
        }
        try {
            const base = document.querySelector('base')?.href || location.href;
            const response = await fetch(new URL('api/beta-testers', base), { cache: 'no-store' });
            if (!response.ok) throw new Error('beta list unavailable');
            const result = await response.json();
            if (!Array.isArray(result.members)) throw new Error('invalid beta list');
            renderBetaHelpers(result.members.map(member => ({ name: member.name, role: 'beta testing', img: member.avatar })));
            betaStatus.textContent = 'live Discord beta tester list · refreshes every 10 minutes';
        } catch {
            betaStatus.textContent = 'live list temporarily unavailable; showing saved beta tester credits';
        }
    }
    refreshBetaTesters();
    setInterval(refreshBetaTesters, 10 * 60 * 1000);
    // game credits — pull thumbnails from the catalog so cards match
    games.innerHTML = '';
    const all = [{ name: 'pizza tower', img: 'assets/btn-pizzatower.png' }, ...MODS, ...FANGAMES];
    for (const g of all) {
        const card = document.createElement('a');
        card.className = 'cr-card cr-game';
        const destination = GAME_CREDIT_LINKS[g.name];
        card.href = destination || 'https://www.google.com/search?q=' + encodeURIComponent('"' + g.name + '" ' + (GAME_CREDITS[g.name] || '') + ' game original page');
        card.target = '_blank';
        card.rel = 'noopener noreferrer';
        card.title = destination ? 'Open game or creator page (new tab)' : 'Find original game page (new tab)';
        card.innerHTML =
            `<img class="cr-ava" src="${creditImage(g.img)}" alt="">` +
            `<span class="cr-info"><span class="cr-name">${g.name}</span><span class="cr-role">${GAME_CREDITS[g.name] || 'unknown'}</span><span class="cr-link-label">${destination ? 'game / creator page' : 'find original page'} ↗</span></span>`;
        games.appendChild(card);
    }
}
renderCredits();
</script>
<script>// Shared site music — plays on every site page (not game pages),
// resumes its position so it feels continuous when navigating.

// Site themes: bg = background image, song = music track.
// cls = optional extra class on .bgimg.
const PU_THEMES = [
    { name: 'Halloween 2026', bg: 'assets/halloween.png', song: 'assets/theme-halloween.ogg', buttonLayout: 'center' },
    { name: 'the tower',      bg: 'assets/bg.gif',            song: 'assets/theme.mp3' },
    { name: 'oregano desert', bg: 'assets/bg-desert.webp',    song: 'assets/theme-desert.ogg' },
    { name: 'pizzaland',      bg: 'assets/bg-pizzaland.webp', song: 'assets/theme-funiculi.ogg' },
    { name: "what's with these pizza guys?", bg: 'assets/bg-pizzaguys.png', song: 'assets/theme-pizzaguys.mp3' },
];

const puTheme = PU_THEMES.find(t => t.name === localStorage.getItem('pu_theme')) || PU_THEMES[0];

// apply the theme's background on every page that loads this script
const bgimgEl = document.querySelector('.bgimg');
if (bgimgEl) {
    bgimgEl.src = puTheme.bg;
    bgimgEl.className = 'bgimg ' + (puTheme.cls || '');
}

const bgm = new Audio(puTheme.song);
bgm.loop = true;
bgm.volume = localStorage.getItem('pu_vol') != null ? +localStorage.getItem('pu_vol') / 100 : 1;
const bgmWanted = localStorage.getItem('pu_audio') !== 'off';
const bgmPos = +localStorage.getItem('pu_pos') || 0;
let bgmStarted = false;

function kickBgm() {
    // dataset.gameOpen = a game is open in the overlay — never start over it
    if (bgmStarted || !bgmWanted || document.body.dataset.gameOpen) return;
    try { bgm.currentTime = bgmPos; } catch {}
    bgm.play()
        .then(() => {
            bgmStarted = true;
            document.removeEventListener('click', kickBgm);
            document.removeEventListener('keydown', kickBgm);
        })
        .catch(() => {}); // autoplay blocked — wait for an interaction
}
document.addEventListener('click', kickBgm);
document.addEventListener('keydown', kickBgm);
kickBgm(); // try immediately — allowed once the site has been interacted with before

// keep position saved so the next page picks up where this one left off
setInterval(() => { if (bgmStarted) localStorage.setItem('pu_pos', bgm.currentTime); }, 2000);
window.addEventListener('beforeunload', () => {
    if (bgmStarted) localStorage.setItem('pu_pos', bgm.currentTime);
});
</script>
<script>/* Pizza Unblocked — device detection.
   Sets window.PU_DEVICE to 'mobile' or 'pc', tags <body> with
   device-mobile / device-pc, and fills #devLine where present. */
(function () {
    const ua = navigator.userAgent;
    const mobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini|Mobile/i.test(ua)
        || ((navigator.maxTouchPoints || 0) > 1 && window.matchMedia && matchMedia('(pointer: coarse)').matches);
    window.PU_DEVICE = mobile ? 'mobile' : 'pc';
    document.documentElement.classList.add('device-' + window.PU_DEVICE);
    if (document.body) document.body.classList.add('device-' + window.PU_DEVICE);
    else addEventListener('DOMContentLoaded', () => document.body.classList.add('device-' + window.PU_DEVICE));
    const el = document.getElementById('devLine');
    if (el) el.textContent = 'device: ' + window.PU_DEVICE + (mobile ? ' (touch controls on in games)' : '');
})();
</script>
<script>// Shared card rendering, favorites, and local play history for every copy of the site.
const ITCH_PROXY = 'https://pizza-game-module-proxy.sm64noahm.workers.dev/itch/';
const LIBRARY_ITEMS = [
    { name: 'pizza tower', desc: 'the original game', dir: 'pizzatower', img: 'assets/btn-pizzatower.png', libraryType: 'game' },
    ...MODS.map(g => ({ ...g, libraryType: 'mod' })),
    ...FANGAMES.filter(g => !g.hideFromLibrary).map(g => ({
        ...g,
        libraryType: g.category === 'extras' ? 'extra' : g.ext ? 'web' : 'game',
    })),
];
const LIBRARY_KEYS = {
    favorites: 'pu_favorite_games_v1',
    history: 'pu_recent_games_v1',
    continue: 'pu_continue_game_v1',
};

function gameUrl(g) {
    if (!g.ext) return (g.category || 'games') + '/' + g.dir + '/';
    return g.ext.replace(/^https?:\/\/html(-classic)?\.itch\.zone\/html\//, ITCH_PROXY);
}

function siteAssetUrl(path) {
    if (window.PU_HOST) return new URL(path, window.PU_HOST.replace(/\/?$/, '/') ).href;
    if (location.protocol === 'file:') return new URL(path, location.pathname.replace(/[^/]*$/, '')).href;
    return new URL(path, location.origin + '/').href;
}

function gameKey(g) {
    return `${g.libraryType || 'game'}:${g.dir || g.ext || g.name}`;
}

function decodeGameKey(value) {
    try { return decodeURIComponent(value || ''); } catch { return ''; }
}

function readLibraryJson(key, fallback) {
    try {
        const value = JSON.parse(localStorage.getItem(key) || 'null');
        return value ?? fallback;
    } catch { return fallback; }
}

function favoriteKeys() {
    const keys = readLibraryJson(LIBRARY_KEYS.favorites, []);
    return new Set(Array.isArray(keys) ? keys : []);
}

function playHistory() {
    const rows = readLibraryJson(LIBRARY_KEYS.history, []);
    return Array.isArray(rows) ? rows : [];
}

function libraryTags(g) {
    const tags = [g.libraryType];
    if (g.ext) tags.push('web');
    if (g.save || g.save101) tags.push('save');
    if (/online|multiplayer|co-?op/i.test(`${g.name} ${g.desc || ''}`)) tags.push('online');
    return tags;
}

function favoriteButton(key) {
    const selected = favoriteKeys().has(key);
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'favorite-toggle';
    button.dataset.gameKey = encodeURIComponent(key);
    button.setAttribute('aria-label', selected ? 'Remove from favorites' : 'Add to favorites');
    button.setAttribute('aria-pressed', String(selected));
    button.title = selected ? 'remove favorite' : 'add to favorites';
    button.textContent = selected ? '★' : '☆';
    return button;
}

function renderCards(gridEl, emptyEl, list) {
    if (!gridEl) return;
    gridEl.replaceChildren();
    const favorites = favoriteKeys();
    for (const g of list) {
        const key = gameKey(g);
        const article = document.createElement('article');
        article.className = 'library-card';
        article.dataset.gameKey = encodeURIComponent(key);

        const favorite = favoriteButton(key);
        article.appendChild(favorite);

        const link = document.createElement(g.action ? 'button' : 'a');
        link.className = 'card';
        if (g.action) {
            link.type = 'button';
            link.dataset.cardAction = g.action;
        } else {
            link.setAttribute('href', gameUrl(g));
        }
        link.dataset.gameKey = encodeURIComponent(key);
        link.setAttribute('aria-label', `${g.action ? 'Open' : 'Play'} ${g.name}`);

        const thumb = document.createElement('div');
        thumb.className = 'thumb';
        const image = document.createElement('img');
        image.src = g.img.startsWith('assets/') ? siteAssetUrl(g.img) : g.img;
        image.alt = g.name;
        image.loading = 'lazy';
        image.decoding = 'async';
        thumb.appendChild(image);
        link.appendChild(thumb);

        const name = document.createElement('div');
        name.className = 'cname';
        name.textContent = g.name;
        link.appendChild(name);

        const tags = document.createElement('div');
        tags.className = 'card-tags';
        for (const tag of libraryTags(g)) {
            const pill = document.createElement('span');
            pill.className = 'library-tag-pill';
            pill.textContent = ({ mod: 'mod', game: 'game', extra: 'extra', web: 'web game', save: 'save', online: 'online' })[tag] || tag;
            tags.appendChild(pill);
        }
        link.appendChild(tags);

        if (g.desc) {
            const desc = document.createElement('p');
            desc.className = 'cdesc';
            desc.textContent = g.desc;
            link.appendChild(desc);
        }
        article.appendChild(link);
        gridEl.appendChild(article);
    }
    if (emptyEl) emptyEl.hidden = list.length > 0;
    syncFavoriteButtons(favorites);
}

function syncFavoriteButtons(keys = favoriteKeys()) {
    for (const button of document.querySelectorAll('.favorite-toggle')) {
        const key = decodeGameKey(button.dataset.gameKey);
        const selected = keys.has(key);
        button.textContent = selected ? '★' : '☆';
        button.setAttribute('aria-pressed', String(selected));
        button.setAttribute('aria-label', selected ? 'Remove from favorites' : 'Add to favorites');
        button.title = selected ? 'remove favorite' : 'add to favorites';
    }
}

function recordGameLaunch(anchor) {
    const key = decodeGameKey(anchor?.dataset.gameKey);
    const item = LIBRARY_ITEMS.find(g => gameKey(g) === key);
    if (!item) return;
    const history = playHistory();
    const previous = history.find(row => row.key === key);
    const row = { key, lastPlayed: Date.now(), plays: (previous?.plays || 0) + 1 };
    localStorage.setItem(LIBRARY_KEYS.history, JSON.stringify([row, ...history.filter(x => x.key !== key)].slice(0, 30)));
    localStorage.setItem(LIBRARY_KEYS.continue, key);
    document.dispatchEvent(new CustomEvent('pu:history-changed'));
}

document.addEventListener('click', event => {
    const button = event.target.closest('.favorite-toggle');
    if (!button) return;
    event.preventDefault();
    event.stopPropagation();
    const key = decodeGameKey(button.dataset.gameKey);
    const keys = favoriteKeys();
    if (keys.has(key)) keys.delete(key); else keys.add(key);
    localStorage.setItem(LIBRARY_KEYS.favorites, JSON.stringify([...keys]));
    syncFavoriteButtons(keys);
    document.dispatchEvent(new CustomEvent('pu:favorites-changed'));
});

function setupSearch(inputEl, gridEl, emptyEl, list) {
    if (!inputEl) return;
    const filter = () => {
        const q = inputEl.value.trim().toLowerCase();
        const filtered = q ? list.filter(g => `${g.name} ${g.desc || ''} ${libraryTags(g).join(' ')}`.toLowerCase().includes(q)) : list;
        renderCards(gridEl, emptyEl, filtered);
    };
    inputEl.addEventListener('input', filter);
}

function setupCatalogFilters(inputEl, filterEl, gridEl, emptyEl, list, categoryFor) {
    if (!filterEl) {
        setupSearch(inputEl, gridEl, emptyEl, list);
        return;
    }
    let active = 'all';
    const render = () => {
        const q = (inputEl?.value || '').trim().toLowerCase();
        const filtered = list.filter(item => {
            const categoryMatch = active === 'all'
                || (active === 'favorites' ? favoriteKeys().has(gameKey(item)) : categoryFor(item) === active);
            const searchMatch = !q || `${item.name} ${item.desc || ''} ${libraryTags(item).join(' ')}`.toLowerCase().includes(q);
            return categoryMatch && searchMatch;
        });
        renderCards(gridEl, emptyEl, filtered);
        for (const button of filterEl.querySelectorAll('[data-catalog-filter]')) {
            const selected = button.dataset.catalogFilter === active;
            button.classList.toggle('selected', selected);
            button.setAttribute('aria-pressed', String(selected));
        }
    };
    inputEl?.addEventListener('input', render);
    filterEl.addEventListener('click', event => {
        const button = event.target.closest('[data-catalog-filter]');
        if (!button || !filterEl.contains(button)) return;
        active = active === button.dataset.catalogFilter ? 'all' : button.dataset.catalogFilter;
        render();
    });
    document.addEventListener('pu:favorites-changed', render);
    render();
}

// Hover sound for catalog cards.
const hoverSfx = new Audio('assets/sfx/buttons.ogg');
hoverSfx.volume = 0.6;
hoverSfx.preload = 'auto';
document.addEventListener('mouseover', event => {
    if (event.target.closest('.card, .favorite-toggle, .icon-btn, .pizza-icon')) {
        hoverSfx.currentTime = 0;
        hoverSfx.play().catch(() => {});
    }
});
</script>
<script>// Unified library page plus the three personal game shelves on the home screen.
(() => {
    let activeFilter = 'all';
    const search = document.getElementById('librarySearch');
    const tagSelect = document.getElementById('libraryTag');
    const sortSelect = document.getElementById('librarySort');
    const grid = document.getElementById('libraryGrid');
    const empty = document.getElementById('libraryEmpty');

    function itemFor(key) {
        return LIBRARY_ITEMS.find(item => gameKey(item) === key);
    }

    function filterMatches(item) {
        if (activeFilter === 'favorites' && !favoriteKeys().has(gameKey(item))) return false;
        if (activeFilter !== 'all' && activeFilter !== 'favorites' && item.libraryType !== activeFilter) return false;
        const selectedTag = tagSelect?.value || 'all';
        if (selectedTag !== 'all' && !libraryTags(item).includes(selectedTag)) return false;
        const query = (search?.value || '').trim().toLowerCase();
        return !query || `${item.name} ${item.desc || ''} ${libraryTags(item).join(' ')}`.toLowerCase().includes(query);
    }

    function sortItems(items) {
        const rows = playHistory();
        const history = new Map(rows.map(row => [row.key, row]));
        const mode = sortSelect?.value || 'az';
        return items.sort((a, b) => {
            if (mode === 'za') return b.name.localeCompare(a.name);
            if (mode === 'recent') return (history.get(gameKey(b))?.lastPlayed || 0) - (history.get(gameKey(a))?.lastPlayed || 0) || a.name.localeCompare(b.name);
            if (mode === 'most') return (history.get(gameKey(b))?.plays || 0) - (history.get(gameKey(a))?.plays || 0) || a.name.localeCompare(b.name);
            return a.name.localeCompare(b.name);
        });
    }

    function renderLibraryPage() {
        if (!grid) return;
        const matches = sortItems(LIBRARY_ITEMS.filter(filterMatches));
        renderCards(grid, empty, matches);
        document.querySelectorAll('#libraryFilters [data-library-filter]').forEach(button => {
            const selected = button.dataset.libraryFilter === activeFilter;
            button.classList.toggle('selected', selected);
            button.setAttribute('aria-pressed', String(selected));
        });
    }

    function renderHomeShelves() {
        const recentRows = playHistory();
        const byKey = new Map(LIBRARY_ITEMS.map(item => [gameKey(item), item]));
        const continuedKey = localStorage.getItem(LIBRARY_KEYS.continue) || '';
        const continued = byKey.get(continuedKey);
        const recent = recentRows.map(row => byKey.get(row.key)).filter(Boolean).slice(0, 6);
        const favorites = LIBRARY_ITEMS
            .filter(item => favoriteKeys().has(gameKey(item)))
            .sort((a, b) => a.name.localeCompare(b.name))
            .slice(0, 6);

        renderCards(document.getElementById('continueGrid'), document.getElementById('continueEmpty'), continued ? [continued] : []);
        renderCards(document.getElementById('recentGrid'), document.getElementById('recentEmpty'), recent);
        renderCards(document.getElementById('favoritesGrid'), document.getElementById('favoritesEmpty'), favorites);
    }

    document.getElementById('libraryFilters')?.addEventListener('click', event => {
        const button = event.target.closest('[data-library-filter]');
        if (!button) return;
        activeFilter = button.dataset.libraryFilter;
        renderLibraryPage();
    });
    document.addEventListener('click', event => {
        const button = event.target.closest('[data-library-filter]');
        if (!button || document.getElementById('libraryFilters')?.contains(button)) return;
        activeFilter = button.dataset.libraryFilter;
        if (typeof showPage === 'function') showPage('library');
        renderLibraryPage();
    });
    search?.addEventListener('input', renderLibraryPage);
    tagSelect?.addEventListener('change', renderLibraryPage);
    sortSelect?.addEventListener('change', renderLibraryPage);
    document.addEventListener('pu:favorites-changed', () => { renderHomeShelves(); renderLibraryPage(); });
    document.addEventListener('pu:history-changed', () => { renderHomeShelves(); renderLibraryPage(); });

    window.renderLibraryPage = renderLibraryPage;
    window.renderHomeShelves = renderHomeShelves;
    renderHomeShelves();
    renderLibraryPage();
})();
</script>
<script>(function () {
    const grid = document.getElementById('modGrid');
    const empty = document.getElementById('modsEmpty');
    const category = item => {
        const text = `${item.name} ${item.desc || ''}`.toLowerCase();
        if (/\blap\b|lapper/.test(text)) return 'lap';
        return 'other';
    };
    setupCatalogFilters(document.getElementById('modSearch'), document.getElementById('modFilters'), grid, empty, MODS, category);
